  """jnp.sign(x) except x=0 is assumed to have a sign of +1, not 0."""
  return jnp.where(x < 0, -1, +1)


def remove_zero(x):
  """Shifts `x` away from 0."""
  return jnp.where(jnp.abs(x) < tiny_val, tiny_val, x)


def clip_finite(x):
